query:
-- Plantes Burkina manquantes
SELECT id, name FROM plants WHERE name LIKE '%Daniellia%' OR name LIKE '%Boswellia%' OR name LIKE '%Xylopia%';

-- Molécules clés
SELECT id, name FROM molecules WHERE name IN ('α-Pinène', 'alpha-Pinène', 'Alpha-Pinène', 'β-Caryophyllène', 'beta-Caryophyllène', 'Khusimol', 'Eugénol', 'Limonène', 'Camphre') LIMIT 15;

-- Recettes Mossi
SELECT id, name FROM recettes WHERE name LIKE '%Mossi%' OR name LIKE '%OS ROUGE%' OR name LIKE '%PÉTRICHOR%' OR name LIKE '%Petrichor%' LIMIT 10;

